function LadderStruggleRecordDialog:InitComponent()
    local param1 = CfUtils.GetCfVo(self.component.settingIdParamVo, ParamVo, 12)

    RecordNumMax = checkNumber(param1.num)

    -- 修改页面的背景
    local bgNode = self.controller.transform:Find("BgNode/ImgBG")
    if isNotNull(bgNode) then
        local AImg = bgNode.gameObject:GetComponent(typeof(RawImageAlterable))
