function LadderStruggleRecordDialog:LoopModeFreshRewardCellList(maxNum)
    if not self.LoopListView.IsListViewInit then
        self.LoopListView:InitListView(maxNum, Bind(self, self.OnGetItemByIndex))
    else
        GameUtils.ReloadData(self.LoopListView, maxNum)
    end
end

function LadderStruggleRecordDialog:OnGetItemByIndex(loopListView, index)
    if index < 0 then
        return nil
    end

    local cell = loopListView:NewListViewItem("Cell")
    local LB_cell = GetLuaBehaviour(cell.gameObject, CellLuaPath)
    if not cell.IsInitHandlerCalled then
        cell.IsInitHandlerCalled = true
        LB_cell:Init()
        LB_cell.Env:SetSystem(self.systemName)
    end
    local data = self.data[index + 1]
    local LT_cell = LB_cell.Env
    LT_cell:UpdateData(self:ConvertData(data))

    return cell
end

--- 请求战斗记录
function LadderStruggleRecordDialog:RequestBattleRecord()
    local succeed = false
    local operation = GameUtils.Request(self.component.InterfaceRecord, {}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        succeed = true
        local jsonData = response.data
        self.data = jsonData.record
    end)

    while not succeed do
        cs_coroutine.yield_return()
    end

    if not succeed then
        self.data = {}
    end
end

--- 把服务器的数据转换为cell需要的格式
---@param data any
function LadderStruggleRecordDialog:ConvertData(data)
    if isNull(data) then
        return
    end
    local playerInfo = data.playerInfo
    local d = {}
    d.rank = data.ranking
    d.name = playerInfo.name
    d.level = playerInfo.level
    d.avatar = playerInfo.avatar
    d.avatarFrame = playerInfo.avatarFrame
    d.combatValue = data.combatValue
    d.battleResult = data.isPassed
    d.attackOrDefence = data.questType
    d.rankChangeState = data.rankingType
    d.rankChange = data.rankingChange
    d.videoId = data.videoId
    d.createTime = data.createTime
    d.playerTeam = data.playerTeam
    d.enemyTeam = data.enemyTeam
    return d
end

